mapper.insert:
insert into member (
	name
	, email
	, pwd
	, nickname
	, gender
	, birth
	, phone
) values (
	#{member.name}
	, #{member.email}
	, #{member.pwd}
	, #{member.nickname}
	, #{member.gender}
	, #{member.birth}
	, #{member.phone}
)

mapper.select:
select count(*)
from member
where nickname = #{nickname}
	and mno != #{mno}

select count(*)
from member
where phone= #{phone}
	and mno!= #{mno}

mapper.update:
update member
set active =#{active}
where mno = #{mno} and role = 'USER'
